sp_ListarHistoricoStatus	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarHistoricoStatus`(IN p_idPedido INT)\nBEGIN\n\n    SELECT\n\n        h.idHistorico,\n\n        h.idPedido,\n\n        h.statusPedido_id,\n\n        h.dthAlteracao,\n\n        h.observacao,\n\n        u.Nome AS nomeUsuario\n\n    FROM PedidoStatusHistorico h\n\n    JOIN Usuario u ON u.idUsuario = h.idUsuario\n\n    WHERE h.idPedido = p_idPedido\n\n    ORDER BY h.dthAlteracao ASC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
